<?php
require __DIR__.'/../server/seo_structure.php';
function check($ok, $message) { if (!$ok) throw new RuntimeException($message); }
$home = '<html><head><link rel="canonical" href="https://rentmor.pl/"></head><body><nav><div><a href="/" aria-label="RentMor.pl — strona główna"><img src="/rentmor-logo.png" alt="RentMor.pl"></a><a href="tel:733891281">Telefon</a></div></nav><h1>Katalog</h1><div id="products">KEEP CARDS</div><section><h2>Wynajem sprzętu budowlanego i ogrodniczego w Krakowie</h2><p>Szukasz sprzętu</p></section><section id="poradniki">old guide</section><section id="wynajem-sprzetu-krakow">old local</section><footer>KEEP FOOTER</footer></body></html>';
if (isset($argv[1])) $home = file_get_contents($argv[1]);
$out = rentmor_seo_structure($home);
check(str_contains($out, 'data-rm-home-structure="v1"'), 'Known live home sections replaced');
check(substr_count($out, 'id="poradniki"') === 1, 'One guides section');
check(substr_count($out, 'id="wynajem-sprzetu-krakow"') === 1, 'One rental section');
check(!str_contains($out, 'Szukasz sprzętu do remontu'), 'Removed duplicate introduction');
check(rentmor_seo_structure($out) === $out, 'Idempotent HTML');
foreach (rm_categories() as $slug=>$cat) check(str_contains($out, 'href="/'.$slug.'/"'), 'Category linked');
check(substr_count($out, 'id="rm-category-menu"') === 1, 'One header menu');
check(!str_contains($out, 'class="rm-seo-links"'), 'No duplicate lower category navigation');
preg_match('~<h1\\b~', $out, $firstHeading, PREG_OFFSET_CAPTURE);
check(isset($firstHeading[0][1]) && strpos($out, 'id="rm-category-menu"') < $firstHeading[0][1], 'Menu above content');
check(str_contains($out, 'href="tel:733891281"'), 'Phone preserved');
$schema = ['@context'=>'https://schema.org','@type'=>'Product','name'=>'Test </script>','offers'=>['@type'=>'Offer','url'=>'https://rentmor.pl/test/','price'=>'130','priceCurrency'=>'PLN','availability'=>'https://schema.org/InStock']];
$product = '<html><head><link rel="canonical" href="https://rentmor.pl/test/"><script type="application/ld+json">'.rm_category_json($schema).'</script></head><body><h1>Test</h1><p>130 zł / doba</p><form action="/">FORM</form></body></html>';
$rendered = rentmor_seo_structure($product);
preg_match('~<script type="application/ld\+json">(.*?)</script>~s', $rendered, $m);
$node = json_decode($m[1], true, 512, JSON_THROW_ON_ERROR);
check($node['offers']['price'] === '130', 'Price unchanged');
check($node['offers']['priceSpecification']['referenceQuantity']['unitCode'] === 'DAY', 'One day');
check($node['offers']['businessFunction'] === 'http://purl.org/goodrelations/v1#LeaseOut', 'Rental');
check(!isset($node['offers']['availability']), 'No unverified stock assertion');
check(str_contains($rendered, '<form action="/">FORM</form>'), 'Form unchanged');
check(str_contains($rendered, 'data-rm-rental-terms="v1"'), 'Visible terms');
check(!str_contains($rendered, 'id="poradniki"'), 'No home content on product');
$perfFixture = '<html><head><link rel="canonical" href="https://rentmor.pl/"><link rel="preload" as="image" href="/assets/rentmor-blueprint-mobile-20261102.webp"></head><body><nav><a href="/"><img src="/rentmor-logo.png?v=rm-20261030-wordmark-v2" srcset="/rentmor-logo.png?v=rm-20261030-wordmark-v2 1x"></a></nav><header data-rentmor-blueprint="v1" style="background-image:url(/assets/rentmor-blueprint-mobile-20261102.webp)"></header></body></html>';
$perfOut = rentmor_seo_structure($perfFixture);
check(substr_count($perfOut, '/assets/rentmor-blueprint-mobile-20261103-lite.webp') === 2, 'Preload and CSS use lighter mobile hero');
check(!str_contains($perfOut, '/assets/rentmor-blueprint-mobile-20261103.webp'), 'Previous hero not downloaded');
check(strpos($perfOut, 'rentmor-blueprint-mobile-20261103-lite.webp') < strpos($perfOut, '<link rel="canonical"'), 'Hero preloaded before canonical') ;
check(!str_contains($perfOut, '/assets/rentmor-blueprint-mobile-20261102.webp'), 'Old mobile hero not loaded');
check(str_contains($perfOut, 'src="/assets/rentmor-logo-mobile-20261103.webp"'), 'Optimized logo used');
check(str_contains($perfOut, 'srcset="/assets/rentmor-logo-mobile-20261103.webp 1x"'), 'Logo srcset aligned');
check(rentmor_seo_structure($perfOut) === $perfOut, 'Optimized HTML idempotent');
$offerOnly = str_replace('href="https://rentmor.pl/"', 'href="https://rentmor.pl/test/"', $perfFixture);
check(str_contains(rentmor_seo_structure($offerOnly), '/assets/rentmor-blueprint-mobile-20261102.webp'), 'Offer image unchanged');
$detailFixture = '<html><head><link rel="canonical" href="https://rentmor.pl/puzzi/"></head><body><div class="rm-gallery"><img data-rm-image-kind="detail" src="/uploads/puzzi.jpg" alt="Puzzi" fetchpriority="high"></div></body></html>';
$detailManifest = ['puzzi.jpg'=>['card'=>['url'=>'/uploads/rentmor-webp/puzzi-card.webp','width'=>640],'detail'=>['url'=>'/uploads/rentmor-webp/puzzi-detail.webp','width'=>1080]]];
$preload = rm_product_lcp_preload($detailFixture, $detailManifest);
check(str_contains($preload, 'imagesrcset="/uploads/rentmor-webp/puzzi-card.webp 640w, /uploads/rentmor-webp/puzzi-detail.webp 1080w"'), 'Preload selects exact approved WebP candidates');
check(str_contains($preload, 'imagesizes="(max-width: 768px) 100vw, 900px"'), 'Preload matches detail image sizes');
check(str_contains($preload, 'fetchpriority="high" data-rm-lcp-preload="v1"'), 'Preload is priority-hinted and unique');
check(strpos($preload, 'data-rm-lcp-preload="v1"') < strpos($preload, '<link rel="canonical"'), 'Preload discovered at head start');
$webpSource = str_replace('src="/uploads/puzzi.jpg"', 'src="https://rentmor.pl/uploads/rentmor-webp/puzzi-detail.webp"', $detailFixture);
check(str_contains(rm_product_lcp_preload($webpSource, $detailManifest), 'data-rm-lcp-preload="v1"'), 'Previously optimized image source resolves via manifest');
check(rm_product_lcp_preload($preload, $detailManifest) === $preload, 'Preload helper idempotent');
check(rm_product_lcp_preload($detailFixture, ['puzzi.jpg'=>['card'=>['url'=>'https://invalid.local/image.webp','width'=>640]]]) === $detailFixture, 'Unsafe image manifest ignored');
check(rm_product_lcp_preload('<html><head></head><body></body></html>', $detailManifest) === '<html><head></head><body></body></html>', 'Unknown page unchanged');
check(rentmor_seo_structure('{"ok":true}') === '{"ok":true}', 'Non HTML unchanged');
$items = rm_category_items([['name'=>'Puzzi','cat'=>'czyszczace','price'=>50],['name'=>'Młot','category'=>'budowlane','price'=>60],['name'=>'Puzzi','cat'=>'czyszczace'],['name'=>'Nowy sprzęt','cat'=>'czyszczące']], 'czyszczace');
check(count($items) === 2 && isset($items['puzzi'], $items['nowy-sprzet']), 'Category matching and deduplication');
check(rm_related_price(['price'=>'<script>']) === '', 'Invalid price excluded');
check(str_contains(rm_category_escape('<script>'), '&lt;script&gt;'), 'Escaping');
[$fallback, $srcset] = rm_category_responsive_image('/uploads/a.jpg', ['a.jpg'=>['small'=>['url'=>'/uploads/rentmor-webp/a-small.webp','width'=>320],'card'=>['url'=>'/uploads/rentmor-webp/a-card.webp','width'=>640]]]);
check($fallback==='/uploads/rentmor-webp/a-card.webp' && str_contains($srcset,'a-small.webp 320w'), 'Responsive WebP variants');
[$fallback, $srcset] = rm_category_responsive_image('/uploads/a.jpg', ['a.jpg'=>['card'=>['url'=>'https://attacker.invalid/image.webp','width'=>640]]]);
check($fallback==='/uploads/a.jpg' && $srcset==='', 'Reject manifest URL outside expected public uploads');

// Unknown templates must keep their original content rather than remove selected pieces.
$unknown = str_replace('Szukasz sprzętu', 'Changed layout', $home);
if (!isset($argv[1])) check(str_contains(rentmor_seo_structure($unknown), 'old local'), 'Unknown layout retained');
echo "PASS: homepage consolidation, categories, schema semantics, price preservation, escaping, forms, idempotence\n";
